// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const { createFormBrowserHarness } = require('./form-browser-harness.js');

/** The shared fake DOM has no event phases; model them here to exercise the vendor click interception. */
function addBrowserEvents(harness) {
    const captureListeners = new WeakMap();
    const decorate = (element) => {
        if (captureListeners.has(element)) {
            return element;
        }
        const captures = new Map();
        captureListeners.set(element, captures);
        const add = element.addEventListener.bind(element);
        const remove = element.removeEventListener.bind(element);
        element.addEventListener = (type, handler, options) => {
            captures.set(handler, options === true || !!(options && options.capture));
            add(type, handler);
        };
        element.removeEventListener = (type, handler, options) => {
            captures.delete(handler);
            remove(type, handler, options);
        };
        if (element.tagName) {
            element.click = () => dispatch(element, 'click');
        }
        if (element.tagName === 'TEXTAREA') {
            element.select = () => {
                element.selectionStart = 0;
                element.selectionEnd = element.value.length;
            };
        }
        return element;
    };
    const create = harness.document.createElement.bind(harness.document);
    harness.document.createElement = (tag) => decorate(create(tag));
    decorate(harness.document);
    decorate(harness.document.body);

    function dispatch(target, type, fields = {}) {
        const event = Object.assign({
            type, target, currentTarget: null, bubbles: true, defaultPrevented: false,
            propagationStopped: false, immediateStopped: false,
            preventDefault() { this.defaultPrevented = true; },
            stopPropagation() { this.propagationStopped = true; },
            stopImmediatePropagation() { this.immediateStopped = true; this.propagationStopped = true; }
        }, fields);
        const path = [];
        for (let node = target; node; node = node.parentNode) {
            path.push(node);
        }
        if (!path.includes(harness.document)) {
            path.push(harness.document);
        }
        const invoke = (element, capture) => {
            event.currentTarget = element;
            const captures = captureListeners.get(element) || new Map();
            for (const handler of (element.eventHandlers.get(type) || []).slice()) {
                if (!!captures.get(handler) === capture) {
                    handler.call(element, event);
                }
                if (event.immediateStopped) {
                    break;
                }
            }
        };
        for (const element of path.slice().reverse()) {
            invoke(element, true);
            if (event.propagationStopped) {
                break;
            }
        }
        if (!event.propagationStopped) {
            for (const element of path) {
                invoke(element, false);
                if (event.propagationStopped) {
                    break;
                }
            }
        }
        // HTML buttons without an explicit type submit their enclosing form after click handlers finish.
        const button = target.closest ? target.closest('button') : null;
        if (type === 'click' && !event.defaultPrevented && button && !button.disabled
            && (!button.type || button.type === 'submit')) {
            const form = button.closest('form');
            if (form) {
                form.submit();
            }
        }
        return event;
    }
    return { decorate, dispatch };
}

function createHarness() {
    const copied = [];
    const harness = createFormBrowserHarness({
        globals: { URLSearchParams },
        workbench: { icons: { copyText: (button, text) => copied.push({ button, text }) } }
    });
    const events = addBrowserEvents(harness);
    harness.loadScripts(['querySharing.js']);
    const form = events.decorate(harness.registerElement('form', { id: 'query-form' }));
    harness.document.body.appendChild(form);
    function editor(initialValue = 'ASK {}') {
        let value = initialValue;
        const wrapper = events.decorate(harness.registerElement('div', { className: 'yasqe' }));
        const buttons = events.decorate(harness.registerElement('div', { className: 'yasqe_buttons' }));
        const share = events.decorate(harness.registerElement('div', {
            className: 'yasqe_share', attributes: { role: 'button', tabindex: '0', 'aria-label': 'Share query' }
        }));
        const icon = events.decorate(harness.registerElement('svg'));
        share.appendChild(icon);
        buttons.appendChild(share);
        wrapper.appendChild(buttons);
        form.appendChild(wrapper);
        const vendorCalls = [];
        share.addEventListener('click', () => {
            vendorCalls.push('share');
            throw new Error('The vendor share handler must not run');
        });
        const instance = {
            getWrapperElement: () => wrapper,
            getValue: () => value,
            setValue: (next) => { value = next; }
        };
        return { instance, wrapper, share, icon, vendorCalls };
    }
    return Object.assign(harness, events, { editor, form, copied,
        install: harness.context.workbench.querySharing.installShareMenu });
}

function popup(editor) {
    return editor.wrapper.querySelector('.yasqe_sharePopup');
}

function button(editor, label) {
    const result = popup(editor).querySelectorAll('button').find((item) => item.textContent === label);
    assert.ok(result, 'popup contains the ' + label + ' action');
    return result;
}

test('Share opens one selectable link and intercepts the vendor handler, including SVG clicks', () => {
    const harness = createHarness();
    const editor = harness.editor();
    const link = 'https://example.org/workbench/repositories/demo/query#query=ASK+%7B%7D';
    const menu = harness.install(editor.instance, { getShareLink: () => link, getCurlCommand: () => 'curl test' });
    harness.dispatch(editor.icon, 'click');
    const field = popup(editor).querySelector('textarea');
    assert.equal(field.value, link);
    assert.equal(field.readOnly, true);
    assert.equal(field.getAttribute('aria-label'), 'Query share link');
    assert.equal(harness.document.activeElement === field, true);
    assert.equal(field.selectionStart, 0);
    assert.equal(field.selectionEnd, link.length);
    assert.deepEqual(editor.vendorCalls, []);
    assert.equal(harness.form.submitCount, 0);
    harness.dispatch(editor.share, 'click');
    assert.equal(popup(editor), null, 'a second press closes the current popup');
    harness.dispatch(editor.share, 'click');
    assert.equal(editor.wrapper.querySelectorAll('.yasqe_sharePopup').length, 1);
    menu.dispose();
});

test('copy actions copy the displayed link and cURL without submitting the Query form', () => {
    const harness = createHarness();
    const editor = harness.editor();
    const link = 'https://example.org/query#query=ASK+%7B%7D';
    const command = "curl 'https://example.org/rdf4j-server/repositories/demo' --data-urlencode 'query=ASK {}'";
    const menu = harness.install(editor.instance, { getShareLink: () => link, getCurlCommand: () => command });
    harness.dispatch(editor.share, 'click');
    const copyLink = button(editor, 'Copy link');
    const copyCurl = button(editor, 'Copy cURL');
    assert.equal(copyLink.type, 'button');
    assert.equal(copyCurl.type, 'button');
    harness.dispatch(copyLink, 'click');
    harness.dispatch(copyCurl, 'click');
    assert.deepEqual(harness.copied.map((entry) => entry.text), [link, command]);
    assert.equal(harness.copied[1].button === copyCurl, true);
    const field = popup(editor).querySelector('textarea');
    assert.equal(field.value, command, 'the command remains available for manual copying');
    assert.equal(field.getAttribute('aria-label'), 'cURL command');
    assert.equal(harness.form.submitCount, 0);
    assert.deepEqual(editor.vendorCalls, []);
    menu.dispose();
});

test('a share menu reads the chosen editor when opened and when its copy actions are used', () => {
    const harness = createHarness();
    const primary = harness.editor('ASK { ?primary ?p ?o }');
    const comparison = harness.editor('ASK { ?comparison ?p ?o }');
    const menus = [primary, comparison].map((editor) => harness.install(editor.instance, {
        getShareLink: () => 'shared:' + editor.instance.getValue(),
        getCurlCommand: () => 'curl:' + editor.instance.getValue()
    }));
    harness.dispatch(comparison.share, 'click');
    assert.equal(popup(comparison).querySelector('textarea').value, 'shared:ASK { ?comparison ?p ?o }');
    comparison.instance.setValue('ASK { ?editedComparison ?p ?o }');
    harness.dispatch(button(comparison, 'Copy cURL'), 'click');
    assert.equal(harness.copied[0].text, 'curl:ASK { ?editedComparison ?p ?o }');
    assert.equal(primary.instance.getValue(), 'ASK { ?primary ?p ?o }');
    menus.forEach((menu) => menu.dispose());
});

test('Escape closes the popup and returns focus to its Share button', () => {
    const harness = createHarness();
    const editor = harness.editor();
    const menu = harness.install(editor.instance, { getShareLink: () => 'link', getCurlCommand: () => 'curl test' });
    harness.dispatch(editor.share, 'click');
    const field = popup(editor).querySelector('textarea');
    const event = harness.dispatch(field, 'keydown', { key: 'Escape' });
    assert.equal(event.defaultPrevented, true);
    assert.equal(popup(editor), null);
    assert.equal(harness.document.activeElement === editor.share, true);
    menu.dispose();
});

test('outside clicks, close and disposal remove popups and document listeners', () => {
    const harness = createHarness();
    const editor = harness.editor();
    const baseline = harness.document.listenerCounts();
    const menu = harness.install(editor.instance, { getShareLink: () => 'link', getCurlCommand: () => 'curl test' });
    harness.dispatch(editor.share, 'click');
    harness.dispatch(harness.document.body, 'click');
    assert.equal(popup(editor), null);
    assert.deepEqual(harness.document.listenerCounts(), baseline);
    harness.dispatch(editor.share, 'click');
    menu.close();
    assert.equal(popup(editor), null);
    assert.deepEqual(harness.document.listenerCounts(), baseline);
    harness.dispatch(editor.share, 'click');
    menu.dispose();
    assert.equal(popup(editor), null);
    assert.deepEqual(harness.document.listenerCounts(), baseline);
    assert.equal(editor.wrapper.listenerCount('click'), 0, 'disposal removes its wrapper interception');
});

test('a cURL generation error leaves the share link available and does not report a copy', () => {
    const harness = createHarness();
    const editor = harness.editor();
    const link = 'https://example.org/query#query=ASK+%7B%7D';
    const menu = harness.install(editor.instance, {
        getShareLink: () => link,
        getCurlCommand: () => harness.context.workbench.querySharing.buildCurlCommand({
            serverUrl: 'file:///srv/rdf4j', repositoryId: 'demo', workbenchUrl: link,
            query: editor.instance.getValue(), infer: true
        })
    });
    harness.dispatch(editor.share, 'click');
    harness.dispatch(button(editor, 'Copy cURL'), 'click');
    assert.equal(popup(editor).querySelector('textarea').value, link);
    assert.match(popup(editor).textContent, /HTTP or HTTPS RDF4J Server endpoint/);
    assert.equal(harness.copied.length, 0);
    assert.equal(harness.form.submitCount, 0);
    harness.dispatch(button(editor, 'Copy link'), 'click');
    assert.equal(harness.copied[0].text, link, 'link sharing remains available without a direct HTTP endpoint');
    menu.dispose();
});
